.version 7.8
.target sm_89
.address_size 64

.visible .entry max_reduce_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 D0,
    .param .u32 D1,
    .param .u32 D2,
    .param .u32 dim,
    .param .u32 out_size
