    mov.u32 %r7, %ntid.x;
    mov.u32 %r8, %tid.x;
    mad.lo.u32 %r9, %r6, %r7, %r8;

    setp.ge.u32 %p1, %r9, %r5;
    @%p1 bra DONE;

    mul.lo.u32 %r10, %r2, %r3;

    setp.eq.u32 %p2, %r4, 0;
    @%p2 bra DIM0;
    setp.eq.u32 %p3, %r4, 1;
    @%p3 bra DIM1;
