    div.u32 %r12, %r9, %r3;
    mad.lo.u32 %r13, %r12, %r3, %r11;
    mov.u32 %r14, %r10;
    mov.u32 %r15, %r1;
    bra COMPUTE;

DIM1:
    rem.u32 %r11, %r9, %r3;
    div.u32 %r12, %r9, %r3;
    mad.lo.u32 %r13, %r12, %r10, %r11;
    mov.u32 %r14, %r3;
    mov.u32 %r15, %r2;
    bra COMPUTE;

DIM2:
    rem.u32 %r11, %r9, %r2;
    div.u32 %r12, %r9, %r2;
    mul.lo.u32 %r16, %r11, %r3;
